impl Solution {
    pub fn max_in_table(n: u32) -> u32 {
        let n = n as usize;
        let mut table = vec![vec![1; n]; n];
        for i in 1..n {
            for j in 1..n {
                table[i][j] = table[i-1][j] + table[i][j-1];
            }
        }
        table[n-1][n-1]
    }
}

